#include <iostream>
struct Pair {
    int value[2] = {3, 7};
    int& operator[](int i) { return value[i]; }
    const int& operator[](int i) const { return value[i]; }
};
int main() {
    Pair p;
    int& alias = p[0];
    alias = p[1];
    const Pair& c = p;
    std::cout << c[0] << ' ' << c[1];
}

